package io.github.phiscript.assets;
import java.io.*;import java.net.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;import java.util.concurrent.atomic.*;import org.json.*;import io.github.phiscript.engine.*;import android.content.Context;import android.net.Uri;
public final class ExternalTest{
 static int checks,requests;static byte[] response;static int status=200;static long length=-1;static String content="application/octet-stream",location=null;
 static void ok(boolean v,String m){checks++;if(!v)throw new AssertionError(m);}
 interface Call{void run()throws Exception;}static void fails(Call r,String m)throws Exception{boolean fail=false;try{r.run();}catch(Exception e){fail=true;}ok(fail,m);}
 static byte[] zip(String...pairs)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(b)){for(int i=0;i<pairs.length;i+=2){z.putNextEntry(new ZipEntry(pairs[i]));z.write(pairs[i+1].getBytes(StandardCharsets.UTF_8));z.closeEntry();}}return b.toByteArray();}
 static PhiraImportData decode(byte[] b,String n){return PhiraImportDecoder.INSTANCE.decode(new ByteArrayInputStream(b),n);}
 public static void main(String[] args)throws Exception{
  Context.root=Files.createTempDirectory("phi-import-test").toFile();Context context=new Context();String fixture=new String(Files.readAllBytes(Paths.get("upstream/updates/data1.0.9/patch/tests/fixtures/pgr_v3_multihold.json")),StandardCharsets.UTF_8);
  JSONObject pgr=new JSONObject(fixture).put("blockAreaList",new JSONArray().put(new JSONObject("{\"bottomLeftPercentage\":{\"x\":0.4,\"y\":0.4},\"topRightPercentage\":{\"x\":0.6,\"y\":0.6},\"appearTime\":0,\"enableTime\":0,\"disableTime\":9,\"disappearTime\":10}")));fixture=pgr.toString();final String phi=fixture;
  byte[] pez=zip("chart.json",fixture,"info.txt","#\nName: Test Song\nLevel: IN Lv.12\nChart: chart.json\nOffset: 0.25\n");PhiraImportData data=decode(pez,"sample.pez");ok(data.getTitle().equals("Test Song"),"PEZ name");ok(data.getLevel().contains("IN"),"PEZ level");Chart chart=Chart.Companion.parse(data.getNormalizedJson());ok(chart.getNotes().size()==7,"PEZ notes");ok(Math.abs(chart.getOffsetSeconds()-.25)<1e-9,"PEZ offset");ok(BlockAreaSet.count(chart)==1,"PGR noise preserved on import");
  String rpe=new String(Files.readAllBytes(Paths.get("upstream/updates/data1.0.9/patch/tests/fixtures/rpe_empty_layers_bpm_parent.json")),StandardCharsets.UTF_8);byte[] archive=zip("folder/chart.json",rpe,"folder/info.yml","name: RPE Test\nlevel: HD 10\nchart: chart.json\n");ok(decode(archive,"nested.zip").getTitle().equals("RPE Test"),"nested RPE ZIP");
  fails(()->decode(zip("../chart.json",phi),"bad.zip"),"path traversal rejected");fails(()->decode(zip("a.json",phi,"b.json",phi),"ambiguous.zip"),"ambiguous chart rejected");fails(()->decode(zip("a.json",phi,"info.yml","chart: missing.json"),"missing.zip"),"missing target rejected");fails(()->decode("<html>login</html>".getBytes(),"login.json"),"HTML rejected");
  File file=new File(context.getCacheDir(),"example.pez");Files.write(file.toPath(),pez);PhiraLibrary local=PhiraLibrary.Companion.importFiles(new ExternalCharts.Storage(context),Collections.singletonList(Uri.fromFile(file)),s->kotlin.Unit.INSTANCE);
  java.lang.reflect.Method from=ExternalCharts.class.getDeclaredMethod("fromLocal",Context.class,PhiraLibrary.class);from.setAccessible(true);ChartLibrary library=(ChartLibrary)from.invoke(null,context,local);ok(library.songs().get(0).getTitle().equals("Test Song"),"adapter OCR title");String id=library.songs().get(0).getId();ok(library.hasChart(id,"IN"),"canonical difficulty");ok(library.load(id,"IN").getNotes().size()==7,"local load adapter");ok(PhiraLibrary.Companion.restore(new ExternalCharts.Storage(context))!=null,"local persisted");
  Files.write(file.toPath(),"bad".getBytes());fails(()->PhiraLibrary.Companion.importFiles(new ExternalCharts.Storage(context),Collections.singletonList(Uri.fromFile(file)),s->kotlin.Unit.INSTANCE),"bad import rejected");ok(PhiraLibrary.Companion.restore(new ExternalCharts.Storage(context)).getEntries().size()==1,"failed import retains old index");
  JSONObject catalog=new JSONObject(new String(Files.readAllBytes(Paths.get("patch/assets/phigros-cloud-catalog-v1.json")),StandardCharsets.UTF_8));ChartLibrary cloud=ExternalCharts.fromCatalog(context,catalog);ok(cloud.getLocations().size()==1022,"all 1022 entries indexed");int duplicates=0;for(ChartLocation l:cloud.getLocations())if(l.getDifficulty().contains("#"))duplicates++;ok(duplicates==6,"same title/difficulty explicitly separated");
  URL.setURLStreamHandlerFactory(protocol->"https".equals(protocol)?new URLStreamHandler(){protected URLConnection openConnection(URL u){requests++;if(u.getHost().equals("api.feijipan.com")&&u.getPath().equals("/ws/file/redirect"))ok(u.getQuery().startsWith("downloadId=")&&u.getQuery().endsWith("shareId=eTyQ30l7"),"share download parameter order matches live protocol");return new HttpURLConnection(u){public void connect(){}public void disconnect(){}public boolean usingProxy(){return false;}public int getResponseCode(){return status;}public long getContentLengthLong(){return length;}public String getContentType(){return content;}public String getHeaderField(String k){return "Location".equals(k)?location:null;}public InputStream getInputStream(){return new ByteArrayInputStream(response);}public OutputStream getOutputStream(){return new ByteArrayOutputStream();}};}}:null);
  response=fixture.getBytes(StandardCharsets.UTF_8);AtomicBoolean cancel=new AtomicBoolean();int[] progress={0};ok(Arrays.equals(response,ChartDownload.get("https://example.test/a",100000,cancel,(d,t)->progress[0]++)),"unknown length download");ok(progress[0]>0,"progress callback");length=response.length;ok(ChartDownload.get("https://example.test/a",100000,cancel,null).length==response.length,"known length");length=response.length+10;fails(()->ChartDownload.get("https://example.test/a",100000,cancel,null),"truncated download");length=200000;fails(()->ChartDownload.get("https://example.test/a",100000,cancel,null),"declared oversized");length=-1;fails(()->ChartDownload.get("https://example.test/a",100,cancel,null),"stream oversized");content="text/html";fails(()->ChartDownload.get("https://example.test/a",100000,cancel,null),"HTML transport");content="application/octet-stream";status=503;fails(()->ChartDownload.get("https://example.test/a",100000,cancel,null),"server unavailable");status=302;location="http://example.test/b";fails(()->ChartDownload.get("https://example.test/a",100000,cancel,null),"TLS downgrade");location="https://example.test/a";fails(()->ChartDownload.get("https://example.test/a",100000,cancel,null),"redirect loop");status=200;fails(()->ChartDownload.get("http://example.test/a",100000,cancel,null),"HTTP denied");fails(()->ChartDownload.get("file:///etc/passwd",100000,cancel,null),"file denied");cancel.set(true);fails(()->ChartDownload.get("https://example.test/a",100000,cancel,null),"cancel before download");cancel.set(false);
  JSONObject one=new JSONObject().put("share","eTyQ30l7").put("entries",new JSONArray().put(new JSONObject().put("id","65979776813").put("name","Test Song - IN [12.0].json")));ChartLibrary net=ExternalCharts.fromCatalog(context,one);String song=net.songs().get(0).getId();int before=requests;Chart first=ExternalCharts.loadSelected(net,song,"IN",cancel);Chart second=ExternalCharts.loadSelected(net,song,"IN",cancel);ok(requests==before+2,"every performance downloads fresh");ok(first!=second&&second.getNotes().size()==7,"new chart each play");
  File cached=new File(context.getFilesDir(),"phigros-cloud-v1/charts/eTyQ30l7-65979776813.json");ok(cached.isFile(),"download cache saved");byte[] old=Files.readAllBytes(cached.toPath());response="bad".getBytes();fails(()->ExternalCharts.loadSelected(net,song,"IN",cancel),"bad new download stops");ok(Arrays.equals(old,Files.readAllBytes(cached.toPath())),"bad download retains valid cache without playing fallback");response=fixture.getBytes(StandardCharsets.UTF_8);cancel.set(true);before=requests;fails(()->ExternalCharts.loadSelected(net,song,"IN",cancel),"cancelled selected download");ok(requests==before,"no request on cancelled performance");
  PhiraImportData named=decode(ExternalCharts.namedPackage(phi.getBytes(StandardCharsets.UTF_8),"Direct Song - HD [10.0].json"),"temporary.pez");ok(named.getTitle().equals("Direct Song")&&named.getLevel().equals("HD"),"direct link preserves filename identity");
  File catalogFile=new File(context.getFilesDir(),"phigros-cloud-v1/catalog.json");Files.write(catalogFile.toPath(),one.toString().getBytes(StandardCharsets.UTF_8));
  ok(ExternalCharts.deleteCacheFiles(context,Collections.singletonList(cached))==0&&!cached.exists(),"single cache deletion");ok(catalogFile.exists(),"deletion retains catalog");
  File foreign=new File(context.getFilesDir(),"unrelated.json");Files.write(foreign.toPath(),new byte[]{1});fails(()->ExternalCharts.deleteCacheFiles(context,Collections.singletonList(foreign)),"deletion cannot leave cache directory");ok(foreign.exists(),"unrelated file retained");
  System.out.println("PASS import/cloud/transport "+checks+" assertions; 1022 catalog entries");
 }
}
